import json, os, subprocess, time, threading
from pathlib import Path
import psycopg
from psycopg.rows import dict_row

root=Path('/home/octadim/MyProjects/Multi_User_RAG_Assist_System')
base=Path('/tmp/rag-lease-root-cause-7')
assert not base.exists()
env=os.environ.copy()
for key,value in {'RAG_MODEL_PATH':'Qwen3.5-2B-Q4_K_M.gguf','RAG_E5_DIR':'e5','RAG_OCR_DIR':'ocr'}.items():env[key]=str(root/'backend/.venv/rag-native-models'/value)
env['RAG_DIAG_PRINTED_CTX']='0'
env['RAG_DIAG_SUPERVISOR_GC']='enabled'
env['PYTHONPATH']='/tmp:'+str(root/'backend')
for model in (root/'backend/.venv/rag-native-models').rglob('*.gguf'):
    with model.open('rb') as handle:os.posix_fadvise(handle.fileno(),0,0,os.POSIX_FADV_DONTNEED)
stop=threading.Event()
start=time.monotonic()

def database_observer():
    connection=None
    lease_connection=None
    with open('/tmp/rag-lease-root-cause-7.pg.jsonl','x',buffering=1) as out:
        while not stop.is_set():
            row={'time':time.time(),'elapsed':time.monotonic()-start}
            try:
                pidfile=base/'postgres0/postmaster.pid'
                if connection is None and pidfile.exists() and len(pidfile.read_text().splitlines())>=5:
                    connection=psycopg.connect(host=pidfile.read_text().splitlines()[4],user='postgres',dbname='postgres',connect_timeout=1,autocommit=True,row_factory=dict_row,options='-c statement_timeout=750')
                if connection:
                    row['activity']=connection.execute("SELECT pid,datname,state,wait_event_type,wait_event,pg_blocking_pids(pid) AS blockers,extract(epoch from clock_timestamp()-query_start)::float AS query_age,extract(epoch from clock_timestamp()-xact_start)::float AS xact_age,left(query,110) AS query FROM pg_stat_activity WHERE backend_type='client backend' AND pid<>pg_backend_pid()").fetchall()
            except Exception as e:
                row['error']=type(e).__name__
                if connection:connection.close();connection=None
            try:
                names=[value['datname'] for value in row.get('activity',[]) if value['datname'].startswith('test_')]
                if lease_connection is None and names:
                    lease_connection=psycopg.connect(host=pidfile.read_text().splitlines()[4],user='postgres',dbname=names[0],connect_timeout=1,autocommit=True,row_factory=dict_row,options='-c statement_timeout=750')
                if lease_connection:
                    row['lease']=lease_connection.execute('SELECT epoch,clock_timestamp()::text AS server_time,healthy_until::text,extract(epoch FROM healthy_until-clock_timestamp())::float AS remaining FROM coordinator_lease WHERE id=1').fetchone()
            except Exception as e:row['lease_error']=type(e).__name__
            row['end_time']=time.time()
            out.write(json.dumps(row,default=str)+'\n')
            stop.wait(.2)
        if connection:connection.close()
        if lease_connection:lease_connection.close()

with open('/tmp/rag-lease-root-cause-7.log','x') as log,open('/tmp/rag-lease-root-cause-7.host.jsonl','x',buffering=1) as host:
    process=subprocess.Popen([str(root/'backend/.venv/bin/python'),'-m','pytest','-c','backend/pyproject.toml','-p','rag_lease_plugin5','backend/tests/browser/test_answer_lifecycle.py::test_actual_print_only_pdf_limitations_reach_answer_passport','-vv','--basetemp='+str(base),'--junitxml=/tmp/rag-lease-root-cause-7.xml'],cwd=root,env=env,stdout=log,stderr=subprocess.STDOUT)
    observer=threading.Thread(target=database_observer);observer.start()
    print('runner',process.pid,flush=True)
    while process.poll() is None:
        row={'time':time.time(),'elapsed':time.monotonic()-start}
        row['pressure']={key:Path('/proc/pressure/'+key).read_text() for key in ('cpu','memory','io')}
        row['memory']={line.split(':')[0]:int(line.split()[1]) for line in Path('/proc/meminfo').read_text().splitlines() if line.startswith(('MemAvailable:','SwapFree:'))}
        stats={}
        for path in Path('/proc').glob('[0-9]*'):
            try:
                values=(path/'stat').read_text().split(') ',1)[1].split()
                stats[int(path.name)]={'ppid':int(values[1]),'state':values[0],'majflt':int(values[9]),'utime':int(values[11]),'stime':int(values[12]),'rss_pages':int(values[21])}
            except (OSError,ValueError,IndexError):pass
        owned={process.pid}
        for _ in range(8):owned.update(pid for pid,value in stats.items() if value['ppid'] in owned)
        row['processes']={pid:value for pid,value in stats.items() if pid in owned}
        for pid,value in row['processes'].items():
            try:
                status=Path(f'/proc/{pid}/status').read_text().splitlines()
                value['swap_kb']=next((int(line.split()[1]) for line in status if line.startswith('VmSwap:')),0)
                value['wchan']=Path(f'/proc/{pid}/wchan').read_text().strip()
            except OSError:pass
        host.write(json.dumps(row)+'\n')
        time.sleep(.2)
    stop.set();observer.join(3)
    print('exit',process.returncode,'elapsed',time.monotonic()-start,flush=True)

